/* ==================== HEADER MOBILE ==================== */
.header-row { 
  display: flex; 
  justify-content: flex-end; 
  align-items: center; 
  flex-shrink: 0; 
  padding: 8px 10px; 
  position: absolute; 
  top: 0;
  left: 0;
  width: 100%;
  z-index: 30;
  background: transparent;
  pointer-events: none;
}

.title-box {
  background: #2a2a2a;
  border: 1px solid #444;
  border-radius: 8px;
  padding: 10px 14px;
  max-width: 68%;
  box-shadow: 0 2px 8px rgba(0,0,0,0.3);
  pointer-events: auto;
  cursor: grab;
  user-select: none;
}

.title { 
  font-size: 15px; 
  font-weight: 700; 
  color: #f8fafc; 
  margin: 0; 
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.subtitle, .sources {
  display: none !important;
}

.actions { 
  display: flex;
  flex-direction: column; 
  gap: 6px; 
  align-items: flex-end;
  position: absolute;
  right: 8px;
  top: 8px;
  z-index: 40;
  pointer-events: auto;
}

.btn { 
  background: #2a2a2a; 
  border: 1px solid #444; 
  color: #f8fafc; 
  padding: 9px;           
  border-radius: 8px;      
  cursor: pointer; 
  display: flex; 
  align-items: center; 
}

.btn:hover { background: #383838; }

.btn svg { 
  width: 24px;             
  height: 24px;            
  fill: currentColor; 
}

.btn.nav-btn { 
  color: #67e8f9; 
  padding: 7px 10px;       
}

.btn.nav-btn svg { 
  width: 26px;             
  height: 26px;            
  stroke: currentColor; 
  stroke-width: 2.5; 
  fill: none; 
}

@media (max-width: 1279px) {
  .title-box {
    position: absolute;
    top: 20px;
    left: 20px;
    z-index: 50;
  }
}

@media (max-width: 1279px) and (hover: none) and (pointer: coarse) {
  #prev-btn, #next-btn { 
    display: none !important; 
  }
}

